# connected components of mismatch positions in top-aligned coordinates
for name, pred in [('u',lambda x,y:x=='8' and y=='9'),('l',lambda x,y:x=='9' and y=='8')]:
 pts={(r,c) for r in range(7) for c in range(27) if pred(a[r][c],b[r][c+2])}
 comps=[]
 while pts:
  seed=pts.pop(); comp={seed}; stack=[seed]
  while stack:
   r,c=stack.pop()
   for q in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
    if q in pts: pts.remove(q); comp.add(q); stack.append(q)
  comps.append(comp)
 print(name, sorted([len(c) for c in comps],reverse=True),[sorted(c) for c in comps])

